import{_ as t,o as i,c as e,a3 as d}from"./chunks/framework.D4-ViStF.js";const g=JSON.parse('{"title":"孔子十翼","description":"《易传》十篇——系辞、文言、说卦、序卦、杂卦（彖、象随六十四卦）——是易经从占卜之书走向义理之学的枢纽。","frontmatter":{"title":"孔子十翼","description":"《易传》十篇——系辞、文言、说卦、序卦、杂卦（彖、象随六十四卦）——是易经从占卜之书走向义理之学的枢纽。","category":"guide","aliases":["孔子十翼","十翼","易传","shi yi"]},"headers":[],"relativePath":"yijing/shi-yi/index.md","filePath":"yijing/shi-yi/index.md","lastUpdated":1787730063000}'),h={name:"yijing/shi-yi/index.md"};function r(n,a,l,o,s,u){return i(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="孔子十翼" tabindex="-1">孔子十翼 <a class="header-anchor" href="#孔子十翼" aria-label="Permalink to &quot;孔子十翼&quot;">​</a></h1><p>「十翼」是《易传》的统称，传统归为孔子及其后学对《易经》的解释文字，好比为「经」插上的十只翅膀。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>十翼共七种、十篇：</p><table tabindex="0"><thead><tr><th>篇名</th><th>分篇</th><th>作用</th><th>本站形态</th></tr></thead><tbody><tr><td>彖传</td><td>上、下</td><td>释卦名、卦辞，断一卦之义</td><td><strong>随六十四卦</strong>（见卦页内嵌）</td></tr><tr><td>象传</td><td>上、下</td><td>释卦象与爻象，大象、小象</td><td><strong>随六十四卦</strong>（见卦页内嵌）</td></tr><tr><td>系辞传</td><td>上、下</td><td>易学总论，讲易理、易用</td><td>独立导读页</td></tr><tr><td>文言传</td><td>—</td><td>专释乾、坤两卦</td><td>独立导读页</td></tr><tr><td>说卦传</td><td>—</td><td>讲八卦的取象与方位</td><td>独立导读页</td></tr><tr><td>序卦传</td><td>—</td><td>讲六十四卦的次序之理</td><td>独立导读页</td></tr><tr><td>杂卦传</td><td>—</td><td>以对比方式点明各卦要义</td><td>独立导读页</td></tr></tbody></table><p>彖、象两传不单独成页：它们本就附着在每一卦的卦辞、爻辞之下，本站已把彖、象原文与字词释义内嵌进各卦页（如 <a href="/Dao/yijing/hexagrams/hexagram-03">屯卦</a>），随逐卦阅读即是读彖、象。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>《易经》原本是占筮之书。正是十翼把卦爻辞背后的<strong>变化之理、忧患意识、修身之道</strong>揭示出来，使它成为一部哲学经典。后来的「义理」一脉，源头就在十翼。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><p>建议顺序：</p><ol><li>先读《系辞传》（<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">上</a> → <a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia">下</a>）——它是进入易学思想的总纲；</li><li>再读《<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a>》《<a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a>》《<a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a>》——建立卦的骨架与关系；</li><li>读《<a href="/Dao/yijing/shi-yi/wen-yan-zhuan">文言传</a>》——看乾、坤两卦被讲透的样板；</li><li>最后随逐卦阅读，回到各卦页里的《彖传》《象传》，以及两篇传之间的互相印证。</li></ol><h2 id="十翼各篇" tabindex="-1">十翼各篇 <a class="header-anchor" href="#十翼各篇" aria-label="Permalink to &quot;十翼各篇&quot;">​</a></h2><ul><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 易之体：易简、观象系辞、大衍之数、一阴一阳之谓道</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia">系辞下传</a> — 易之用：卦爻之变、观象制器、三陈九卦、穷变通久</li><li><a href="/Dao/yijing/shi-yi/wen-yan-zhuan">文言传</a> — 专释乾坤：元亨利贞四德、大人之德、坤道积善</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 八卦取象与方位：乾坤生六子、近取远取、先后天方位</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 卦序之理：从乾坤到未济的连锁逻辑</li><li><a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a> — 卦德速览：乾刚坤柔，比乐师忧</li></ul><h2 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h2><p>待整理。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>与「文王六十四卦」对照：卦爻辞是「经」，十翼是「传」</li><li>与「义理」对照：义理派正是以十翼为宗</li><li>彖、象随逐卦：见 <a href="/Dao/yijing/hexagrams/">六十四卦目录</a></li></ul>',17)])])}const c=t(h,[["render",r]]);export{g as __pageData,c as default};
